<script setup lang="ts">
import {ElButton, ElDialog, ElInputNumber, ElInput, ElTable, ElTableColumn, ElPagination, vLoading} from 'element-plus'
import {computed,ref,watch} from 'vue'
import {api} from '../../api'
import {confirmAction} from '../../shared/confirm'
import {base,reasonText,type DiningTable} from './types'
const editing=ref<DiningTable|null>(null),editNumber=ref('')
const props=defineProps<{restaurantId:string;canManage:boolean}>()
const items=ref<DiningTable[]>([]),numbers=ref(''),selected=ref<DiningTable[]>([]),busy=ref(false),loading=ref(false),error=ref(''),results=ref<string[]>([]),page=ref(1),total=ref(0)
let generation=0,createGeneration=0
async function load(){const current=++generation;loading.value=true;error.value='';try{const result=await api<{items:DiningTable[];total:number}>(`${base}/restaurants/${props.restaurantId}/tables?page=${page.value}&pageSize=20`);if(current===generation){items.value=result.items;total.value=result.total;selected.value=[]}}catch(e){if(current===generation)error.value=reasonText(e)}finally{if(current===generation)loading.value=false}}
const createOpen=ref(false),batchMode=ref(false),preview=ref<string[]>([]),prefix=ref('B'),start=ref(1),end=ref(5)
const previewValid=computed(()=>preview.value.length>0&&preview.value.join('\n')===numbers.value.split(/[\n,，]/).map(s=>s.trim()).filter(Boolean).join('\n'))
function openCreate(batch:boolean){if(busy.value)return;batchMode.value=batch;numbers.value='';preview.value=[];error.value='';createOpen.value=true}
function validate(){preview.value=[];error.value='';const rows=numbers.value.split(/[\n,，]/).map(s=>s.trim()).filter(Boolean);if(!rows.length||rows.length>100||(!batchMode.value&&rows.length!==1)){error.value=batchMode.value?'请输入1至100个桌号。':'请输入一个桌号。';return}if(rows.some(n=>n.length>40)){error.value='桌号不能超过40个字符。';return}if(new Set(rows).size!==rows.length||rows.some(n=>items.value.some(i=>i.number===n))){error.value='存在重复桌号，请修改后重新预览。';return}preview.value=rows}
function sequence(){if(!Number.isInteger(start.value)||!Number.isInteger(end.value)||start.value<1||end.value<start.value||end.value-start.value>=100){error.value='编号范围必须为1至100张。';return}numbers.value=Array.from({length:end.value-start.value+1},(_,i)=>prefix.value+String(start.value+i).padStart(2,'0')).join('\n');validate()}
async function add(){if(busy.value||!props.canManage||!previewValid.value)return;busy.value=true;error.value='';const target=props.restaurantId,current=createGeneration;try{await api(`${base}/restaurants/${target}/tables/batch`,{method:'POST',body:JSON.stringify({numbers:[...preview.value],enabled:true})});if(current!==createGeneration)return;createOpen.value=false;numbers.value='';preview.value=[];await load()}catch(e){if(current===createGeneration)error.value=`${reasonText(e)}；已保留桌号输入，请核对后重试。`}finally{if(current===createGeneration)busy.value=false}}
async function toggle(item:DiningTable){if(busy.value||!props.canManage)return;if(!await confirmAction(`确定${item.enabled?'停用':'启用'}餐桌 ${item.number}？停用后原桌码不可进入店铺。`))return;busy.value=true;error.value='';try{await api(`${base}/restaurants/${props.restaurantId}/tables/${item.id}`,{method:'PATCH',body:JSON.stringify({enabled:!item.enabled,revision:item.revision})});await load()}catch(e){error.value=reasonText(e)}finally{busy.value=false}}
async function rename(){if(busy.value||!props.canManage||!editing.value||!editNumber.value.trim())return;busy.value=true;error.value='';try{await api(`${base}/restaurants/${props.restaurantId}/tables/${editing.value.id}`,{method:'PATCH',body:JSON.stringify({number:editNumber.value.trim(),revision:editing.value.revision})});editing.value=null;await load()}catch(e){error.value=`${reasonText(e)}；已保留桌号输入。`}finally{busy.value=false}}
async function exportCodes(){if(busy.value||!props.canManage||!selected.value.length)return;busy.value=true;error.value='';results.value=[];try{for(const item of selected.value){try{const response=await fetch(`/api/v1/admin${base}/restaurants/${props.restaurantId}/tables/${item.id}/code`,{credentials:'same-origin'});if(response.status===401)window.dispatchEvent(new Event('admin-session-expired'));const mime=response.headers.get('content-type')?.split(';')[0]?.trim().toLowerCase();const extension=mime==='image/png'?'png':mime==='image/jpeg'?'jpg':null;if(!response.ok||!extension){let message='微信桌码生成失败，请检查小程序配置。';try{const data=await response.json();message=data.error?.message||message}catch{}throw new Error(message)}const url=URL.createObjectURL(await response.blob());const link=document.createElement('a');link.href=url;link.download=`餐桌-${item.number.replace(/[\\/:*?"<>|]/g,'-')}.${extension}`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);results.value=[...results.value,`${item.number}：微信桌码已下载`]}catch(e){results.value=[...results.value,`${item.number}：${reasonText(e)}`];error.value='部分桌码导出失败，可重新选择失败的餐桌重试。'}}}finally{busy.value=false}}
watch(()=>props.restaurantId,()=>{createGeneration++;busy.value=false;items.value=[];selected.value=[];createOpen.value=false;editing.value=null;preview.value=[];numbers.value='';load()},{immediate:true})
</script>
<template><section class="panel"><h2>餐桌与扫码入口</h2><p>桌号在本店内唯一。每次进入店铺均需重新扫码；下载的是微信真实小程序码。</p><p v-if="error" role="alert" class="error">{{error}} <el-button :disabled="busy" @click="load">重试</el-button></p><div class="toolbar" v-if="canManage"><el-button type="primary" :disabled="busy" @click="openCreate(false)">新建桌码</el-button><el-button :disabled="busy" @click="openCreate(true)">批量新建</el-button><el-button :disabled="!selected.length||busy" :loading="busy" @click="exportCodes">导出所选桌码（{{selected.length}}）</el-button></div><el-table v-loading="loading" :data="items" empty-text="暂无餐桌" @selection-change="selected=$event"><el-table-column v-if="canManage" type="selection" width="50" :selectable="(row:DiningTable)=>row.enabled"/><el-table-column prop="number" label="桌号"/><el-table-column label="状态"><template #default="{row}">{{row.enabled?'启用':'停用'}}</template></el-table-column><el-table-column v-if="canManage" label="操作"><template #default="{row}"><el-button link :disabled="busy" @click="editing={...(row as DiningTable)};editNumber=row.number">编辑桌号</el-button><el-button link :disabled="busy" @click="toggle(row as DiningTable)">{{row.enabled?'停用':'启用'}}</el-button></template></el-table-column></el-table><el-pagination :current-page="page" :total="total" :page-size="20" layout="prev,pager,next,total" @current-change="page=$event;load()"/><form v-if="canManage&&editing" class="toolbar" @submit.prevent="rename"><label>修改桌号<el-input v-model="editNumber" aria-label="修改桌号" maxlength="40" :disabled="busy"/></label><el-button native-type="submit" type="primary" :loading="busy">保存桌号</el-button><el-button :disabled="busy" @click="editing=null">取消</el-button></form><el-dialog v-model="createOpen" :title="batchMode?'批量新建桌码':'新建桌码'" width="min(560px,94vw)" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy"><p>桌号在本店内唯一。保存餐桌记录后，可再下载微信真实桌码。</p><p v-if="error" role="alert" class="error">{{error}}</p><div v-if="batchMode" class="toolbar"><label>前缀<el-input v-model="prefix" aria-label="桌号前缀" maxlength="20" :disabled="busy"/></label><label>起始<el-input-number v-model="start" :min="1" :max="99999" :disabled="busy"/></label><label>结束<el-input-number v-model="end" :min="1" :max="99999" :disabled="busy"/></label><el-button :disabled="busy" @click="sequence">生成预览</el-button></div><label for="table-numbers">{{batchMode?'桌号（每行一个，最多100个）':'桌号'}}</label><el-input id="table-numbers" v-model="numbers" type="textarea" :rows="batchMode?5:1" :disabled="busy" maxlength="4100"/><div class="toolbar"><el-button :disabled="busy" @click="validate">校验并预览</el-button></div><p v-if="previewValid" role="status">校验通过，共 {{preview.length}} 张：{{preview.join('、')}}。其他页的桌号由服务器统一校验。</p><p v-else class="muted">创建前须校验并预览；重复桌号阻止提交。</p><template #footer><el-button :disabled="busy" @click="createOpen=false">取消</el-button><el-button type="primary" :disabled="!previewValid||busy" :loading="busy" @click="add">创建餐桌</el-button></template></el-dialog><ul v-if="results.length" aria-live="polite"><li v-for="result in results" :key="result">{{result}}</li></ul></section></template>
